tool.command:

  ln -f -s ${input_results_npz_path} ${input_results_npz_path}_`echo $$`.${input_results_npz_path.ext};

  ln -f -s ${input_stats_pt_path} ${input_stats_pt_path}_`echo $$`.${input_stats_pt_path.ext};

  ln -f -s ${input_topology_path} ${input_topology_path}_`echo $$`.${input_topology_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

feat2traj

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____cc____cc__'
  #end if

  #if str($input_results_npz_path) != 'None':
    --input_results_npz_path ${input_results_npz_path}_`echo $$`.${input_results_npz_path.ext}
  #end if

  #if str($input_stats_pt_path) != 'None':
    --input_stats_pt_path ${input_stats_pt_path}_`echo $$`.${input_stats_pt_path.ext}
  #end if

  #if str($input_topology_path) != 'None':
    --input_topology_path ${input_topology_path}_`echo $$`.${input_topology_path.ext}
  #end if


  --output_traj_path $outname_output_traj_path

  --output_top_path $outname_output_top_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_results_npz_path}_`echo $$`.${input_results_npz_path.ext};

  rm -f ${input_stats_pt_path}_`echo $$`.${input_stats_pt_path.ext};

  rm -f ${input_topology_path}_`echo $$`.${input_topology_path.ext};


  if test -f $outname_output_traj_path; then mv $outname_output_traj_path $output_traj_path; fi;

  if test -f $outname_output_top_path; then mv $outname_output_top_path $output_top_path; fi;
